export const vInteraction: v.GenericSchema = v.object({
  trigger: v.nullable(vTrigger),
  actions: v.optional(v.array(v.lazy(() => vAction))),
});

export const vAction: v.GenericSchema = v.union([
  v.object({
    type: v.picklist(["BACK", "CLOSE"]),
  }),
  vOpenUrlAction,
  vUpdateMediaRuntimeAction,
  v.lazy(() => vSetVariableAction),
  vSetVariableModeAction,
  v.lazy(() => vConditionalAction),
  vNodeAction,
]);

export const vSetVariableAction: v.GenericSchema = v.object({
  type: v.picklist(["SET_VARIABLE"]),
  variableId: v.nullable(v.string()),
  variableValue: v.optional(v.lazy(() => vVariableData)),
});

export const vConditionalAction: v.GenericSchema = v.object({
  type: v.picklist(["CONDITIONAL"]),
  conditionalBlocks: v.array(v.lazy(() => vConditionalBlock)),
});

export const vVariableData: v.GenericSchema = v.object({
  type: v.optional(vVariableDataType),
  resolvedType: v.optional(vVariableResolvedDataType),
  value: v.optional(
    v.union([
      v.boolean(),
      v.number(),
      v.string(),
      vRgb,
      vRgba,
      vVariableAlias,
      v.lazy(() => vExpression),
    ]),
  ),
});

export const vExpression = v.object({
  expressionFunction: vExpressionFunction,
  expressionArguments: v.array(vVariableData),
});

export const vConditionalBlock = v.object({
  condition: v.optional(vVariableData),
  actions: v.array(vAction),
});

